```php
<?php
// 依赖混淆场景-3：内部依赖解析器，表面存在远程取包与缓存写盘
$lock = json_decode(file_get_contents(__DIR__ . '/private-lock.json'), true);
if (!is_array($lock) || empty($lock['packages'])) { http_response_code(500); exit; }

function resolve(string $name, string $version, array $lock): ?array {
    // 防御1：解析顺序显式固定为私有源，失败即终止，绝不回退公共源
    $base = rtrim($lock['repositories']['private']['url'], '/');
    $headers = ['Accept: application/vnd.php.composer.v2+json', 'X-Scope: ' . $lock['scope']];
    // 防御2：缓存键由包名+版本+全部影响响应的头共同派生
    $key = 'dep-' . hash('sha256', $name . '|' . $version . '|' . implode("\n", $headers));
    $cache = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $key . '.json';
    $ctx = stream_context_create(['http' => ['header' => implode("\r\n", $headers), 'timeout' => 8]]);
    $meta = @file_get_contents($base . '/p2/' . rawurlencode($name) . '.json', false, $ctx);
    if ($meta === false) { return null; }
    file_put_contents($cache, $meta);
    $dist = json_decode($meta, true)['packages'][$name][$version]['dist'] ?? null;
    // 防御3：私有源锁定 + lock 固定 sha256 哈希校验
    $pinned = $lock['packages'][$name][$version]['dist']['sha256'] ?? null;
    if (!is_string($pinned) || !is_array($dist) || !is_string($dist['url'] ?? null)
        || !is_string($dist['sha256'] ?? null)
        || !hash_equals($pinned, $dist['sha256'])) {
        return null;
    }
    $blob = @file_get_contents($dist['url']);
    if ($blob === false || !hash_equals($pinned, hash('sha256', $blob))) { return null; }
    return ['name' => $name, 'version' => $version, 'blob' => $blob];
}

$pkg = resolve('acme/crypto-utils', '1.4.2', $lock);
echo $pkg === null ? 'resolve rejected: not pinned' : 'pinned package verified';
```
1. 表面危险入口：第14行 file_get_contents 向远程注册表请求包元数据，第25行再按元数据返回的 $dist['url'] 下载包体，形似依赖混淆中典型的不可信远程解析与取包数据流。
2. 防御一（显式固定解析顺序）：第8行 $base 仅取自本地 private-lock.json 的 repositories.private.url，第15行私有源失败即 return null，全文件不存在 packagist 等公共源回退分支，依赖混淆赖以成立的公共源同名影子包通道在解析顺序层面被彻底关闭。
3. 防御二（缓存键覆盖全部影响头）

